// ============================================================
// Market Hours Gate
// ============================================================
// Only proceed during market hours: 9:30 AM - 4:00 PM ET, Mon-Fri
// If outside market hours, stop execution.
// ============================================================

const now = new Date();

// Convert to ET (n8n should be set to America/New_York timezone)
const hour = now.getHours();
const minute = now.getMinutes();
const day = now.getDay(); // 0=Sun, 1=Mon, ..., 5=Fri, 6=Sat

// Check if it's a weekday
if (day === 0 || day === 6) {
  // Weekend - stop
  return [];
}

// Check market hours (9:30 AM to 4:00 PM ET)
const timeInMinutes = hour * 60 + minute;
const marketOpen = 9 * 60 + 30;  // 9:30 AM
const marketClose = 16 * 60;      // 4:00 PM

if (timeInMinutes < marketOpen || timeInMinutes >= marketClose) {
  // Outside market hours - stop
  return [];
}

// Market is open - proceed
return [{ json: { marketOpen: true, timestamp: now.toISOString(), hour, minute, day } }];

// ============================================================
// Altamira Capital - Risk Limit Monitor
// ============================================================
// Checks ALL risk limits from the Risk Management Framework:
//   1. Single position > 5% of portfolio
//   2. Any sector > 25% (tech > 35%)
//   3. Total options allocation > 30% notional
//   4. Cash reserve < 15%
//   5. Net delta outside -30 to +50 range (per $100K)
//   6. Net theta negative
//   7. Drawdown worse than -5% (Tier 1 trigger)
// ============================================================

const allItems = $input.all();
const portfolioData = allItems[0]?.json || {};
const balanceData = allItems[1]?.json || {};

// -----------------------------------------------------------
// Configuration
// -----------------------------------------------------------
const STARTING_CAPITAL = 100000;
const PORTFOLIO_SCALE = 100000; // Per $100K for Greeks limits

const SECTOR_MAP = {
  'AAPL': 'Technology', 'MSFT': 'Technology', 'GOOGL': 'Technology',
  'AMZN': 'Technology', 'META': 'Technology', 'NVDA': 'Technology',
  'AVGO': 'Technology', 'V': 'Financial Services', 'MA': 'Financial Services',
  'COST': 'Consumer Defensive', 'SPY': 'Index'
};

const SECTOR_LIMITS = {
  'Technology': 35,
  'Financial Services': 25,
  'Consumer Defensive': 25,
  'Index': 100, // No limit on index hedging
  'Unknown': 25
};

// -----------------------------------------------------------
// Parse E-Trade Portfolio
// -----------------------------------------------------------
const positions = portfolioData?.PortfolioResponse?.AccountPortfolio?.[0]?.Position || [];

let netDelta = 0;
let netTheta = 0;
let totalOptionsNotional = 0;
let totalPositionValue = 0;

// Track per-position and per-sector exposure
const positionExposures = []; // { ticker, exposure, percent, type }
const sectorExposures = {};   // { sector: totalExposure }

for (const pos of positions) {
  const ticker = pos.Product?.symbol || pos.symbolDescription || 'UNKNOWN';
  const cleanTicker = ticker.split(' ')[0].toUpperCase(); // Strip option suffixes
  const quantity = pos.quantity || 0;
  const marketValue = Math.abs(pos.marketValue || 0);
  const sector = SECTOR_MAP[cleanTicker] || 'Unknown';

  totalPositionValue += marketValue;

  if (pos.Product?.securityType === 'OPTN' || pos.Product?.securityType === 'OPT') {
    // Options position
    const delta = pos.Complete?.delta || pos.delta || 0;
    const theta = pos.Complete?.theta || pos.theta || 0;
    const strikePrice = pos.Product?.strikePrice || pos.strikePrice || 0;

    netDelta += delta * Math.abs(quantity) * 100;
    netTheta += theta * Math.abs(quantity) * 100;

    // Notional = strike * contracts * 100
    const notional = strikePrice * Math.abs(quantity) * 100;
    totalOptionsNotional += notional;

    positionExposures.push({
      ticker: cleanTicker,
      exposure: notional,
      type: 'option',
      sector: sector
    });

    // Add to sector exposure
    sectorExposures[sector] = (sectorExposures[sector] || 0) + notional;
  } else {
    // Equity position
    netDelta += quantity; // 1.0 delta per share

    positionExposures.push({
      ticker: cleanTicker,
      exposure: marketValue,
      type: 'equity',
      sector: sector
    });

    sectorExposures[sector] = (sectorExposures[sector] || 0) + marketValue;
  }
}

// -----------------------------------------------------------
// Parse E-Trade Balance
// -----------------------------------------------------------
const balanceComputed = balanceData?.BalanceResponse?.Computed || balanceData?.BalanceResponse || {};
const cashAvailable = balanceComputed?.cashAvailableForInvestment
  || balanceComputed?.cashBalance
  || balanceComputed?.Cash?.moneyMktBalance
  || 0;
const accountValue = balanceComputed?.RealTimeValues?.totalAccountValue
  || balanceComputed?.accountBalance
  || 0;

const portfolioValue = accountValue || (cashAvailable + totalPositionValue);

// -----------------------------------------------------------
// Run Risk Checks
// -----------------------------------------------------------
const breaches = [];

// CHECK 1: Any single position > 5% of portfolio?
for (const pos of positionExposures) {
  const percent = portfolioValue > 0 ? (pos.exposure / portfolioValue * 100) : 0;
  if (percent > 5) {
    breaches.push({
      check: 'POSITION SIZE',
      severity: 'HIGH',
      message: `${pos.ticker} (${pos.type}) is ${percent.toFixed(1)}% of portfolio (limit: 5%)`,
      value: percent.toFixed(1) + '%',
      limit: '5%',
      action: `Reduce ${pos.ticker} position to bring below 5% of portfolio value`
    });
  }
}

// CHECK 2: Any sector > 25% (tech > 35%)?
for (const [sector, exposure] of Object.entries(sectorExposures)) {
  const percent = portfolioValue > 0 ? (exposure / portfolioValue * 100) : 0;
  const limit = SECTOR_LIMITS[sector] || 25;
  if (percent > limit) {
    breaches.push({
      check: 'SECTOR CONCENTRATION',
      severity: 'HIGH',
      message: `${sector} sector is ${percent.toFixed(1)}% of portfolio (limit: ${limit}%)`,
      value: percent.toFixed(1) + '%',
      limit: limit + '%',
      action: `Reduce ${sector} exposure. Close or trim positions in this sector.`
    });
  }
}

// CHECK 3: Total options allocation > 30% notional?
const optionsPercent = portfolioValue > 0 ? (totalOptionsNotional / portfolioValue * 100) : 0;
if (optionsPercent > 30) {
  breaches.push({
    check: 'OPTIONS ALLOCATION',
    severity: 'HIGH',
    message: `Total options notional is ${optionsPercent.toFixed(1)}% of portfolio (limit: 30%)`,
    value: optionsPercent.toFixed(1) + '%',
    limit: '30%',
    action: 'Close one or more options positions to bring notional below 30%'
  });
}

// CHECK 4: Cash reserve < 15%?
const cashPercent = portfolioValue > 0 ? (cashAvailable / portfolioValue * 100) : 0;
if (cashPercent < 15) {
  breaches.push({
    check: 'CASH RESERVE',
    severity: 'HIGH',
    message: `Cash reserve is ${cashPercent.toFixed(1)}% (minimum: 15%). Cash: $${cashAvailable.toFixed(2)}`,
    value: cashPercent.toFixed(1) + '%',
    limit: '15% minimum',
    action: 'Do NOT open new positions. Close a position to restore cash above 15%.'
  });
}

// CHECK 5: Net delta outside -30 to +50 range (per $100K)?
const scaleFactor = portfolioValue / PORTFOLIO_SCALE;
const deltaLowerLimit = -30 * scaleFactor;
const deltaUpperLimit = 50 * scaleFactor;

if (netDelta < deltaLowerLimit) {
  breaches.push({
    check: 'NET DELTA (LOW)',
    severity: 'MEDIUM',
    message: `Net delta is ${netDelta.toFixed(1)} (lower limit: ${deltaLowerLimit.toFixed(1)} for $${(portfolioValue/1000).toFixed(0)}K portfolio)`,
    value: netDelta.toFixed(1),
    limit: `${deltaLowerLimit.toFixed(1)} to ${deltaUpperLimit.toFixed(1)}`,
    action: 'Portfolio is too short delta. Consider closing short options or adding long equity exposure.'
  });
} else if (netDelta > deltaUpperLimit) {
  breaches.push({
    check: 'NET DELTA (HIGH)',
    severity: 'MEDIUM',
    message: `Net delta is ${netDelta.toFixed(1)} (upper limit: ${deltaUpperLimit.toFixed(1)} for $${(portfolioValue/1000).toFixed(0)}K portfolio)`,
    value: netDelta.toFixed(1),
    limit: `${deltaLowerLimit.toFixed(1)} to ${deltaUpperLimit.toFixed(1)}`,
    action: 'Portfolio is too long delta. Consider trimming equity positions or adding short delta (CSPs do not help here).'
  });
}

// CHECK 6: Net theta negative?
if (netTheta < 0) {
  breaches.push({
    check: 'NET THETA',
    severity: 'MEDIUM',
    message: `Net theta is -$${Math.abs(netTheta).toFixed(2)}/day. Theta should be positive for premium selling strategy.`,
    value: '$' + netTheta.toFixed(2) + '/day',
    limit: 'Positive (>$0/day)',
    action: 'Review options positions. Long options (hedges) may be dragging theta negative. Consider adjusting hedge sizing.'
  });
}

// CHECK 7: Drawdown worse than -5%? (Tier 1 trigger)
const drawdownPercent = portfolioValue > 0 ? ((portfolioValue - STARTING_CAPITAL) / STARTING_CAPITAL * 100) : 0;
// Note: This uses starting capital as reference. In production, use the high watermark from Daily Dashboard.
if (drawdownPercent < -5) {
  let tier = 'Tier 1';
  let severity = 'HIGH';
  let action = 'TIER 1 PROTOCOL: Reduce sizing 25%. No new risk for 2 days. Add hedges. Increase cash to 25%.';

  if (drawdownPercent < -15) {
    tier = 'Tier 3';
    severity = 'CRITICAL';
    action = 'TIER 3 - CAPITAL PRESERVATION: Close ALL options. 60% cash. No new positions for 20 trading days. Full strategy review.';
  } else if (drawdownPercent < -10) {
    tier = 'Tier 2';
    severity = 'CRITICAL';
    action = 'TIER 2 PROTOCOL: Close bottom 50% conviction positions. Reduce sizing 50%. Cash to 40%. No new risk for 5 days.';
  }

  breaches.push({
    check: `DRAWDOWN (${tier})`,
    severity: severity,
    message: `Portfolio drawdown: ${drawdownPercent.toFixed(1)}% from starting capital. ${tier} triggered.`,
    value: drawdownPercent.toFixed(1) + '%',
    limit: '-5% (Tier 1), -10% (Tier 2), -15% (Tier 3)',
    action: action
  });
}

// -----------------------------------------------------------
// Build output
// -----------------------------------------------------------
const hasBreaches = breaches.length > 0;
const hasCritical = breaches.some(b => b.severity === 'CRITICAL');

const now = new Date();
const timestampStr = now.toISOString();

let telegramMessage = '';
if (hasBreaches) {
  const severityIcon = hasCritical ? '\ud83d\udea8' : '\u26a0\ufe0f';
  telegramMessage = `${severityIcon} ALTAMIRA CAPITAL - RISK ALERT ${severityIcon}\n` +
    `Time: ${timestampStr}\n` +
    `Portfolio: $${portfolioValue.toFixed(2)}\n` +
    `===========================================\n\n`;

  for (const breach of breaches) {
    telegramMessage += `[${breach.severity}] ${breach.check}\n` +
      `  ${breach.message}\n` +
      `  ACTION: ${breach.action}\n\n`;
  }

  telegramMessage += `===========================================\n` +
    `CURRENT METRICS:\n` +
    `  Net Delta: ${netDelta.toFixed(1)}\n` +
    `  Net Theta: $${netTheta.toFixed(2)}/day\n` +
    `  Cash: $${cashAvailable.toFixed(2)} (${cashPercent.toFixed(1)}%)\n` +
    `  Options Notional: ${optionsPercent.toFixed(1)}%\n` +
    `  Open Positions: ${positions.length}\n` +
    `===========================================\n` +
    `Rules are not guidelines. Execute the prescribed action.`;
}

return [{
  json: {
    timestamp: timestampStr,
    portfolioValue: portfolioValue,
    hasBreaches: hasBreaches,
    hasCritical: hasCritical,
    breachCount: breaches.length,
    breaches: breaches,
    metrics: {
      netDelta: Math.round(netDelta * 100) / 100,
      netTheta: Math.round(netTheta * 100) / 100,
      cashPercent: Math.round(cashPercent * 100) / 100,
      optionsPercent: Math.round(optionsPercent * 100) / 100,
      drawdownPercent: Math.round(drawdownPercent * 100) / 100,
      positionCount: positions.length
    },
    telegramMessage: telegramMessage
  }
}];

// No breaches detected - silently complete.
// This node exists to cleanly terminate the 'no breach' branch.
// No Telegram message is sent when all limits are within bounds.
return [{ json: { status: 'all_clear', timestamp: new Date().toISOString() } }];
